# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜKÛN SEBEBİYLE OLUŞAN MEDLER: MEDD-İ LÂZIM VE MEDD-İ ÂRIZ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Medd-i Lâzım (الْمَدُّ اللَّازِمُ)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Formül: Harf-i Med (ا، و، ي) + Lâzım Sükûn</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">• Lâzım Sükûn: Durulsa da geçilse de var olan</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" fill="#1e3a8a">asli cezim (ْ) veya şeddedir (ّ).</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• Uzatma: 4 Elif miktarı (Bütün kıraatlerde vacip)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">وَلَا الضَّآلِّينَ · الْحَآقَّةُ · آللّٰهُ · المٓ</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#334155">Şeddeli veya cezimli harften önce med harfi!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Medd-i Ârız (الْمَدُّ الْعَارِضُ)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Formül: Harf-i Med (ا، و، ي) + Ârız (Geçici) Sükûn</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#14532d">• Ârız Sükûn: Kelime sonunda vakıf (duruş) sebebiyle</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" fill="#14532d">ortaya çıkan, geçildiğinde kaybolan sükûndur.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Uzatma: 1 ile 4 Elif arası (Hükmü: Caiz)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">الْعَالَمِينَ (الْعَالَمِينْ) · نَسْتَعِينُ · يَعْلَمُونَ</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#166534">Ayet sonlarında durulduğunda oluşur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KEHF SURESİ 1-10. AYETLERİN TEMEL KONULARI VE MESAJLARI</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Kur\'an\'ın Nitelikleri (1-5)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">الْحَمْدُ لِلّٰهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#713f12">• Allah\'a hamd ile başlar.</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#713f12">• Kur\'an\'da hiçbir eğrilik ve</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#713f12">çelişki yoktur (قَيِّمًا - dosdoğru).</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11" fill="#713f12">• Salih amel işleyen müminlere</text>\n  <text x="125" y="202" text-anchor="middle" font-size="11" fill="#713f12">güzel bir mükâfatı (أَجْرًا حَسَنًا)</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">müjdeler, tevhidi korur.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Dünya İmtihanı (6-8)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#164e63">• Peygamberimiz (sav) inanmayanlar</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#164e63">için aşırı üzülmemesi konusunda</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#164e63">teselli edilir (6. ayet).</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#164e63">• Yeryüzündeki her şey kimin</text>\n  <text x="350" y="198" text-anchor="middle" font-size="11" fill="#164e63">daha güzel amel (أَحْسَنُ عَمَلًا)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">yapacağını sınamak içindir.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. Ashâb-ı Kehf Girişi (9-10)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">أَصْحَابَ الْكَهْفِ وَالرَّقِيمِ</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#581c87">• İnançlarını korumak için</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#581c87">mağaraya sığınan gençler (فِتْيَةٌ).</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Duaları (10. Ayet):</text>\n  <text x="575" y="182" text-anchor="middle" font-size="10" fill="#581c87">رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً</text>\n  <text x="575" y="200" text-anchor="middle" font-size="10" fill="#581c87">وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا</text>\n  <text x="575" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">(Rabbimiz! Katından rahmet ver...)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÖRT FER\'Î MED KURALININ KARŞILAŞTIRMALI ÖZET TABLOSU</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Hemze (ء / أ) Sebebiyle Oluşanlar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">1. Medd-i Muttasıl (Bitişik Med):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#881337">Harf-i med ve hemze AYNI kelimede → جَآءَ ، سُوٓءَ</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Hükmü: Vacip (Asım kıraatinde 4 elif)</text>\n  <text x="180" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">2. Medd-i Munfasıl (Ayrık Med):</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#881337">Harf-i med ve hemze AYRI kelimelerde → يَآ أَيُّهَا</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Hükmü: Caiz (1-4 elif uzatılabilir)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sükûn (ْ / ّ) Sebebiyle Oluşanlar</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3. Medd-i Lâzım (Kalıcı Sükûn):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">Harf-i med + Lâzım Sükûn (cezim/şedde) → الضَّآلِّينَ</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Hükmü: Lâzım / Vacip (4 elif uzatılır)</text>\n  <text x="520" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">4. Medd-i Ârız (Duruş Sükûnu):</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#1e3a8a">Harf-i med + Ârız Sükûn (vakıfta) → تَعْمَلُونَ (تَعْمَلُونْ)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Hükmü: Caiz (Durunca 1-4 elif, geçince tabii)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
